<script setup>
import { onMounted,ref,onBeforeUnmount } from "vue";import { NButton,NEmpty,NInput,NInputNumber,NModal,NForm,NFormItem,NSelect,NTag,NAlert,useDialog,useMessage } from "naive-ui";
import PageShell from "../components/PageShell.vue";import Panel from "../components/Panel.vue";import {healthApi,apiKeysApi} from "../api.js";import {can} from "../access.js";
const health=ref(null),keys=ref([]),loading=ref(false),error=ref(""),open=ref(false),plain=ref(""),busy=ref(false),form=ref({name:"",role:"operator",rateLimitPerMin:60});const dialog=useDialog(),message=useMessage();
const roles=[{label:"运营",value:"operator"},{label:"开发者",value:"developer"},{label:"审计员",value:"auditor"},{label:"所有者",value:"owner"}];
async function load(){loading.value=true;error.value="";try{health.value=await healthApi.get();if(can('workflow.write'))keys.value=await apiKeysApi.list();}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function create(){busy.value=true;try{if(!Number.isInteger(form.value.rateLimitPerMin)||form.value.rateLimitPerMin<1||form.value.rateLimitPerMin>6000)throw Error("每分钟请求上限必须是 1 至 6000 的整数");const result=await apiKeysApi.create(form.value);plain.value=result.key;open.value=false;await load();}catch(e){message.error(e.message);}finally{busy.value=false;}}
async function toggle(item){try{await apiKeysApi.patch(item.id,{disabled:!item.disabled});await load();}catch(e){message.error(e.message);}}
function revoke(item){dialog.warning({title:"吊销 API Key",content:`吊销「${item.name}」后无法恢复，确定继续？`,positiveText:"吊销",negativeText:"取消",onPositiveClick:async()=>{try{await apiKeysApi.revoke(item.id);await load();}catch(e){message.error(e.message);return false;}}});}
async function copy(){try{await navigator.clipboard.writeText(plain.value);message.success("已复制，请妥善保存");}catch{message.error("复制失败，请手动选择并复制");}}
onMounted(load);onBeforeUnmount(()=>{plain.value="";});
</script><template><PageShell title="设置" subtitle="工作空间运行状态与开放接口访问管理" :loading="loading" :error="error"><template #actions><n-button @click="load">刷新</n-button></template><Panel title="运行环境"><dl class="detail-grid"><dt>登录验证</dt><dd>{{health?.auth==='required'?'已开启':'免登录演示'}}</dd><dt>模型运行模式</dt><dd>{{health?.model?.mode==='live'?'真实模型':'模拟模型'}}</dd><dt>存储后端</dt><dd>{{health?.storage?.kind||'—'}}</dd><dt>会话数</dt><dd>{{health?.sessions??'—'}}</dd></dl></Panel><Panel v-if="can('workflow.write')" title="API Key" style="margin-top:20px"><template #actions><n-button type="primary" @click="open=true;form={name:'',role:'operator',rateLimitPerMin:60}">创建 API Key</n-button></template><n-empty v-if="!keys.length" description="还没有 API Key" class="empty-state"/><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>名称</th><th>标识</th><th>角色 / 限流</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in keys" :key="item.id"><td>{{item.name}}</td><td>{{item.prefix}}…</td><td>{{roles.find(r=>r.value===item.role)?.label}} / {{item.rateLimitPerMin}} 次/分钟</td><td><n-tag>{{item.revokedAt?'已吊销':item.disabled?'已停用':'可用'}}</n-tag></td><td><div class="action-row"><n-button :disabled="!!item.revokedAt" size="small" @click="toggle(item)">{{item.disabled?'启用':'停用'}}</n-button><n-button :disabled="!!item.revokedAt" size="small" quaternary type="error" @click="revoke(item)">吊销</n-button></div></td></tr></tbody></table></div></Panel><n-modal v-model:show="open" preset="card" title="创建 API Key" style="width:480px"><n-form label-placement="top"><n-form-item label="名称"><n-input v-model:value="form.name"/></n-form-item><n-form-item label="角色"><n-select v-model:value="form.role" :options="roles"/></n-form-item><n-form-item label="每分钟请求上限"><n-input-number v-model:value="form.rateLimitPerMin" :min="1" :max="6000"/></n-form-item></n-form><template #footer><n-button type="primary" :loading="busy" @click="create">创建</n-button></template></n-modal><n-modal :show="!!plain" preset="card" title="保存 API Key" style="width:560px" @update:show="value=>{if(!value)plain=''}"><n-alert type="warning">明文只显示这一次，关闭后无法找回。请在可信位置妥善保存。</n-alert><n-input :value="plain" readonly style="margin:16px 0"/><div class="action-row"><n-button @click="copy">复制</n-button><n-button type="primary" @click="plain=''">已保存，关闭</n-button></div></n-modal></PageShell></template>
